CREATE TABLE public.properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,label text NOT NULL,property_type text NOT NULL DEFAULT 'house',address_line1 text,address_line2 text,postal_code text,city text,country text NOT NULL DEFAULT 'DE',year_built integer,size_sqm integer,units integer NOT NULL DEFAULT 1,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.properties TO authenticated; GRANT ALL ON public.properties TO service_role;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY; CREATE POLICY properties_own ON public.properties FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS property_id uuid REFERENCES public.properties(id) ON DELETE SET NULL;
CREATE TABLE public.job_bids(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,contractor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,labor_cents integer NOT NULL DEFAULT 0,materials_cents integer NOT NULL DEFAULT 0,travel_cents integer NOT NULL DEFAULT 0,message text,timeline_days integer,valid_until date,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','sent','accepted','declined','withdrawn')),details jsonb,sent_at timestamptz,decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,contractor_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.job_bids TO authenticated; GRANT ALL ON public.job_bids TO service_role;
ALTER TABLE public.job_bids ENABLE ROW LEVEL SECURITY; CREATE POLICY bids_select_participants ON public.job_bids FOR SELECT TO authenticated USING(contractor_id=auth.uid() OR(status<>'draft' AND EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.owner_id=auth.uid()))); CREATE POLICY bids_insert ON public.job_bids FOR INSERT TO authenticated WITH CHECK(contractor_id=auth.uid() AND status IN('draft','sent')); CREATE POLICY bids_update ON public.job_bids FOR UPDATE TO authenticated USING(contractor_id=auth.uid() AND status IN('draft','sent','withdrawn')) WITH CHECK(contractor_id=auth.uid() AND status IN('draft','sent','withdrawn')); CREATE POLICY bids_delete ON public.job_bids FOR DELETE TO authenticated USING(contractor_id=auth.uid() AND status<>'accepted');
CREATE INDEX job_bids_job_idx ON public.job_bids(job_id); CREATE INDEX job_bids_contractor_idx ON public.job_bids(contractor_id);
CREATE TABLE public.site_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL UNIQUE REFERENCES public.jobs(id) ON DELETE CASCADE,homeowner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,contractor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,dates timestamptz[] NOT NULL DEFAULT '{}',slot text NOT NULL DEFAULT 'morning' CHECK(slot IN('morning','afternoon','evening')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_visits TO authenticated; GRANT ALL ON public.site_visits TO service_role;
ALTER TABLE public.site_visits ENABLE ROW LEVEL SECURITY; CREATE POLICY visits_select ON public.site_visits FOR SELECT TO authenticated USING(auth.uid() IN(homeowner_id,contractor_id)); CREATE POLICY visits_insert ON public.site_visits FOR INSERT TO authenticated WITH CHECK(homeowner_id=auth.uid()); CREATE POLICY visits_update ON public.site_visits FOR UPDATE TO authenticated USING(homeowner_id=auth.uid()) WITH CHECK(homeowner_id=auth.uid()); CREATE POLICY visits_delete ON public.site_visits FOR DELETE TO authenticated USING(homeowner_id=auth.uid());
CREATE TABLE public.job_crew(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE,provider_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,member_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(booking_id,member_name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.job_crew TO authenticated; GRANT ALL ON public.job_crew TO service_role;
ALTER TABLE public.job_crew ENABLE ROW LEVEL SECURITY; CREATE POLICY crew_own ON public.job_crew FOR ALL TO authenticated USING(provider_id=auth.uid()) WITH CHECK(provider_id=auth.uid());
CREATE TABLE public.job_hours(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE,provider_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,staff_name text NOT NULL DEFAULT 'Me',hours numeric(6,2) NOT NULL CHECK(hours>0 AND hours<=24),work_date date NOT NULL DEFAULT current_date,note text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.job_hours TO authenticated; GRANT ALL ON public.job_hours TO service_role;
ALTER TABLE public.job_hours ENABLE ROW LEVEL SECURITY; CREATE POLICY hours_own ON public.job_hours FOR ALL TO authenticated USING(provider_id=auth.uid()) WITH CHECK(provider_id=auth.uid());
CREATE TABLE public.staff_gps_pings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,member_id text NOT NULL,member_name text,job text,latitude double precision NOT NULL,longitude double precision NOT NULL,accuracy double precision,recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.staff_gps_pings TO authenticated; GRANT ALL ON public.staff_gps_pings TO service_role;
ALTER TABLE public.staff_gps_pings ENABLE ROW LEVEL SECURITY; CREATE POLICY gps_own ON public.staff_gps_pings FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
ALTER TABLE public.staff_hours ADD COLUMN IF NOT EXISTS job text;
ALTER TABLE public.invoices ADD COLUMN IF NOT EXISTS currency text DEFAULT 'EUR', ADD COLUMN IF NOT EXISTS document_type text DEFAULT 'invoice';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS legal_info jsonb;
CREATE TABLE public.contractor_invoices(id text PRIMARY KEY,owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contractor_invoices TO authenticated; GRANT ALL ON public.contractor_invoices TO service_role;
ALTER TABLE public.contractor_invoices ENABLE ROW LEVEL SECURITY; CREATE POLICY contractor_invoices_own ON public.contractor_invoices FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.site_diary_entries(id text PRIMARY KEY,owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,job_id text NOT NULL,media_key text,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_diary_entries TO authenticated; GRANT ALL ON public.site_diary_entries TO service_role;
ALTER TABLE public.site_diary_entries ENABLE ROW LEVEL SECURITY; CREATE POLICY diary_own ON public.site_diary_entries FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.verification_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN('meisterbrief','handwerksrolle','other')),file_name text NOT NULL,mime text NOT NULL,size integer NOT NULL,media_key text NOT NULL,issuer text,issued_on date,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.verification_documents TO authenticated; GRANT ALL ON public.verification_documents TO service_role;
ALTER TABLE public.verification_documents ENABLE ROW LEVEL SECURITY; CREATE POLICY documents_select ON public.verification_documents FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY documents_insert ON public.verification_documents FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND status='pending' AND reviewed_by IS NULL AND reviewed_at IS NULL); CREATE POLICY documents_delete ON public.verification_documents FOR DELETE TO authenticated USING(owner_id=auth.uid()); CREATE POLICY documents_review ON public.verification_documents FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.help_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 160),kind text NOT NULL CHECK(kind IN('backup','partner','equipment','other')),trade text NOT NULL DEFAULT '',city text NOT NULL DEFAULT '',start_date date,duration_days integer CHECK(duration_days IS NULL OR duration_days BETWEEN 1 AND 365),description text NOT NULL DEFAULT '' CHECK(char_length(description)<=4000),contact_name text NOT NULL DEFAULT '',contact_phone text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.help_requests TO authenticated; GRANT ALL ON public.help_requests TO service_role;
ALTER TABLE public.help_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY help_select ON public.help_requests FOR SELECT TO authenticated USING(true); CREATE POLICY help_insert ON public.help_requests FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid()); CREATE POLICY help_update ON public.help_requests FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid()); CREATE POLICY help_delete ON public.help_requests FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE TABLE public.certificate_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,title text NOT NULL,description text,kind text NOT NULL DEFAULT 'certificate',file_path text NOT NULL,file_name text NOT NULL,mime_type text NOT NULL,merge_fields jsonb NOT NULL DEFAULT '[]',default_values jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.certificate_templates TO authenticated; GRANT ALL ON public.certificate_templates TO service_role;
ALTER TABLE public.certificate_templates ENABLE ROW LEVEL SECURITY; CREATE POLICY templates_own ON public.certificate_templates FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.certificate_issuances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,template_id uuid NOT NULL REFERENCES public.certificate_templates(id) ON DELETE CASCADE,client_id uuid REFERENCES public.clients(id) ON DELETE SET NULL,recipient_name text NOT NULL,recipient_email text,recipient_address text,issued_at date NOT NULL DEFAULT current_date,merged_values jsonb NOT NULL DEFAULT '{}',rendered_path text,rendered_mime text,sent_via text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.certificate_issuances TO authenticated; GRANT ALL ON public.certificate_issuances TO service_role;
ALTER TABLE public.certificate_issuances ENABLE ROW LEVEL SECURITY; CREATE POLICY issuances_own ON public.certificate_issuances FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,plan text NOT NULL DEFAULT 'free',status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY subscriptions_own ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['properties','job_bids','site_visits','certificate_templates'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_updated_at()',t||'_set_updated_at',t); END LOOP; END $$;
CREATE POLICY verification_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='verifications' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY verification_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='verifications' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY verification_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='verifications' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY receipt_files_own ON storage.objects FOR ALL TO authenticated USING(bucket_id='receipts' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='receipts' AND (storage.foldername(name))[1]=auth.uid()::text);